"""SyntheticNormal data of the paper, generated by the reference code.

Usage: python3 -I prepare_data.py <reference repo> <output dir>

CPDDatasets("synthetic_1D" / "synthetic_100D").get_dataset_() of the reference
(utils/datasets.py, unchanged): 1000 sequences of length 128 (500 with a change
of mean from 1 to a random mean in 2-99, 500 without), seed 123, 70/30 split.
For each data set and part, writes <name>_<part>_x.bin (float64, little endian,
array [sequence, time, feature] in C order), <name>_<part>_y.bin (labels,
[sequence, time]) and <name>_<part>.json (dimensions and the indices of the
sequences in the generated data set).
"""

import json
import os
import sys

import numpy as np
import torch

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import ref_env  # noqa: E402

repo, out_dir = sys.argv[1], sys.argv[2]
os.makedirs(out_dir, exist_ok=True)
ref = ref_env.load(repo)
for name in ["synthetic_1D", "synthetic_100D"]:
    train, test = ref["datasets"].CPDDatasets(experiments_name=name).get_dataset_()
    for part, subset in (("train", train), ("test", test)):
        x = torch.stack([subset[i][0] for i in range(len(subset))]).double().numpy()
        y = torch.stack([subset[i][1] for i in range(len(subset))]).double().numpy()
        x.astype("<f8").tofile(os.path.join(out_dir, f"{name}_{part}_x.bin"))
        y.astype("<f8").tofile(os.path.join(out_dir, f"{name}_{part}_y.bin"))
        with open(os.path.join(out_dir, f"{name}_{part}.json"), "w") as f:
            json.dump({"shape": list(x.shape), "indices": [int(i) for i in subset.indices]}, f)
        print(name, part, x.shape, "with change:", int((y.max(axis=1) > 0).sum()))
